# Telemetry: sections read with GET /api/<section> (the reference's schemas,
# with its example values), and the same pushed on the websocket API as an
# api_notification for a subscribed path.
telemetry(GC, "device", inbound_http={
    "path": "/api/device",
    "body": '{"name":"FOH rack","hostname":"gc-foh","description":"","system_id":7,"model":"GigaCore 16Xt",'
            '"mac_address":"00:0a:d5:00:00:01","serial":"16XT-0001","firmware":{"active":"v1.9.2","alternate":"v1.8.0",'
            '"upgrade_in_progress":false},"api_version":"1.5.0","actual_ip":{"ip_address":"10.0.0.10",'
            '"default_gateway":"10.0.0.1","prefix_length":24}}'},
    expect_state={"device": {"name": "FOH rack", "hostname": "gc-foh", "description": "", "system_id": 7,
                             "model": "GigaCore 16Xt", "mac_address": "00:0a:d5:00:00:01", "serial": "16XT-0001",
                             "firmware": {"active": "v1.9.2", "alternate": "v1.8.0", "upgrade_in_progress": False},
                             "api_version": "1.5.0",
                             "actual_ip": {"ip_address": "10.0.0.10", "default_gateway": "10.0.0.1", "prefix_length": 24}}})
telemetry(GC, "ports", inbound_http={
    "path": "/api/ports",
    "body": '{"port":[{"port_number":3,"legend":"Stage left","type":"rj45","enabled":true,"link_state":"up",'
            '"member_of":{"type":"group","id":2},"vlan":{"mode":"untagged","allowed":[10,20],"untagged":10,"pvid":10}}]}'},
    expect_state={"ports": {"port": {"3": {"port_number": 3, "legend": "Stage left", "type": "rj45", "enabled": True,
                                           "link_state": "up", "member_of": {"type": "group", "id": 2},
                                           "vlan": {"mode": "untagged", "allowed": "[10,20]", "untagged": 10, "pvid": 10}}}}})
telemetry(GC, "poe-push", inbound_ws='{"api_notification":{"path":"/api/poe","notification_type":"full_update",'
                                     '"new_value":{"ports":[{"port_number":5,"enabled":false}]}}}',
          expect_state={"poe": {"ports": {"5": {"port_number": 5, "enabled": False}}}})
